        replyAuthor.value = "";
        replyText.value = "";
        showReplyForm.value = false;
        window.location.reload();
      } else {
        const data = await res.json();
        errorMsg.value = data.error || "Failed to submit reply.";
      }
    } catch (err) {
      errorMsg.value = "An error occurred.";
    } finally {
      isSubmitting.value = false;
    }
  });

  return (
    <div
      class="comment-node"
