            />
          </div>
          <div style={{ marginBottom: "5px" }}>
            <textarea
              placeholder="Write a reply..."
              value={replyText.value}
              onInput$={(e) => (replyText.value = (e.target as HTMLTextAreaElement).value)}
              required
              style={{ width: "100%", padding: "5px", height: "60px" }}
            />
          </div>
